package org.example.backtrackweb.sync.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.Instant;

/**
 * The idempotency ledger: one row per operation the server has applied.
 *
 * <p>{@code opId} is generated by the device and is unique <em>inside its
 * business</em> (the database backs that with a unique index on
 * {@code business_id, op_id}), so one business's operation ids can never block
 * or be confused with another's.
 *
 * <p>{@code payloadHash} is the fingerprint of the device, the command type and
 * the canonical form of the payload. It is what lets the server tell a genuine
 * retry - same id, same content, same device - from a reused id carrying
 * different content, which is refused instead of being silently answered with
 * somebody else's result.
 *
 * <p>The row is written in the same transaction as the change it describes, so
 * the two can never disagree.
 */
@Entity
@Table(name = "sync_operations")
public class SyncOperation {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** Generated by the device; unique inside the business, not globally. */
    @Column(name = "op_id", nullable = false, length = 64)
    private String opId;

    @Column(nullable = false)
    private Long businessId;

    private Long deviceId;

    @Column(nullable = false, length = 40)
    private String opType;

    /** Device + command type + canonical payload, hashed. */
    @Column(nullable = false, length = 64)
    private String payloadHash;

    @Column(length = 36)
    private String aggregateUuid;

    @Column(nullable = false)
    private Instant appliedAt = Instant.now();

    /** Position of the resulting change in the business change feed. */
    @Column(nullable = false)
    private long serverSeq;

    @Column(nullable = false, columnDefinition = "text")
    private String resultJson;

    public Long getId() {
        return id;
    }

    public String getOpId() {
        return opId;
    }

    public void setOpId(String opId) {
        this.opId = opId;
    }

    public Long getBusinessId() {
        return businessId;
    }

    public void setBusinessId(Long businessId) {
        this.businessId = businessId;
    }

    public Long getDeviceId() {
        return deviceId;
    }

    public void setDeviceId(Long deviceId) {
        this.deviceId = deviceId;
    }

    public String getOpType() {
        return opType;
    }

    public void setOpType(String opType) {
        this.opType = opType;
    }

    public String getPayloadHash() {
        return payloadHash;
    }

    public void setPayloadHash(String payloadHash) {
        this.payloadHash = payloadHash;
    }

    public String getAggregateUuid() {
        return aggregateUuid;
    }

    public void setAggregateUuid(String aggregateUuid) {
        this.aggregateUuid = aggregateUuid;
    }

    public Instant getAppliedAt() {
        return appliedAt;
    }

    public long getServerSeq() {
        return serverSeq;
    }

    public void setServerSeq(long serverSeq) {
        this.serverSeq = serverSeq;
    }

    public String getResultJson() {
        return resultJson;
    }

    public void setResultJson(String resultJson) {
        this.resultJson = resultJson;
    }
}
